	@Test
	void explicitModesWinOverBuiltInAndUnknownFactoryDefaults() {
		MemoryStore customStore = new MemoryStore();
		customStore.setEvaluationStrategyFactory(new DefaultEvaluationStrategyFactory() {
		});
		for (MemoryStore store : List.of(new MemoryStore(), customStore)) {
			SailRepository repository = new SailRepository(store);
			try (var connection = repository.getConnection()) {
				connection.setQueryParseOptions(QueryParseOptions.STRICT.withGraphAlgebraMode(GraphAlgebraMode.LEGACY));
				var legacy = connection.prepareTupleQuery(QueryLanguage.SPARQL,
						"SELECT * WHERE { GRAPH ?g { ?s ?p ?o } }", null);
				assertEquals(0, graphNodes(legacy.getParsedQuery().getTupleExpr()));
				assertFalse(legacy.getParsedQuery().getParseOptions().blankNodeReferences());

				connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.GRAPH));
				var graph = connection.prepareTupleQuery(QueryLanguage.SPARQL,
						"SELECT * WHERE { GRAPH ?g { ?s ?p ?o } }", null);
				assertEquals(1, graphNodes(graph.getParsedQuery().getTupleExpr()));
				assertEquals(GraphAlgebraMode.LEGACY, legacy.getParsedQuery().getParseOptions().graphAlgebraMode());
			} finally {
				repository.shutDown();
			}
		}
	}

	@Test
	void preparedQueriesKeepTheirModeAndItsEmptyGraphSemantics() {
		SailRepository repository = new SailRepository(new MemoryStore());
		try (var connection = repository.getConnection()) {
			String queryText = "SELECT ?x WHERE { GRAPH <urn:missing> { BIND(1 AS ?x) } }";
			var graph = connection.prepareTupleQuery(QueryLanguage.SPARQL, queryText, null);
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.LEGACY));
			var legacy = connection.prepareTupleQuery(QueryLanguage.SPARQL, queryText, null);
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT);

			try (var result = graph.evaluate()) {
				assertFalse(result.hasNext(), "GRAPH must check that the named graph exists");
			}
			try (var result = legacy.evaluate()) {
				assertTrue(result.hasNext(), "legacy algebra deliberately retains the old missing-graph limitation");
				assertEquals("1", result.next().getValue("x").stringValue());
				assertFalse(result.hasNext());
			}
			assertEquals(GraphAlgebraMode.GRAPH, graph.getParsedQuery().getParseOptions().graphAlgebraMode());
			assertEquals(GraphAlgebraMode.LEGACY, legacy.getParsedQuery().getParseOptions().graphAlgebraMode());
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void preparedUpdatesKeepTheirModeAfterConnectionOptionsChange() {
		SailRepository repository = new SailRepository(new MemoryStore());
		try (var connection = repository.getConnection()) {
			String updateText = "INSERT { <urn:s> <urn:p> ?x } WHERE { GRAPH <urn:missing> { BIND(1 AS ?x) } }";
			SailUpdate graph = (SailUpdate) connection.prepareUpdate(updateText);
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.LEGACY));
			SailUpdate legacy = (SailUpdate) connection.prepareUpdate(updateText);
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT);

			graph.execute();
			assertEquals(0, connection.size());
			legacy.execute();
			assertEquals(1, connection.size());
			assertEquals(GraphAlgebraMode.GRAPH, graph.getParsedUpdate().getParseOptions().graphAlgebraMode());
			assertEquals(GraphAlgebraMode.LEGACY, legacy.getParsedUpdate().getParseOptions().graphAlgebraMode());
		} finally {
			repository.shutDown();
		}
	}

